function memoryArtwork(im,extra=''){return im.viewBox?`<svg ${extra} viewBox="${im.viewBox}" role="presentation" aria-hidden="true"><image href="${esc(im.asset)}" width="${im.width}" height="${im.height}" /></svg>`:`<img ${extra} src="${esc(im.asset)}" alt="" draggable="false">`}
const memoryThemes=[{id:'mixed',name:'Misturar todos',tag:'Uma surpresa em cada par',color:'#7d67b4',mark:'✧'},{id:'toy-story',name:'Toy Story',tag:'Amigos de brinquedo',color:'#e9b64d',mark:'★'},{id:'kpop',name:'Guerreiras do K-pop',tag:'Ritmo e magia',color:'#b67ccf',mark:'♫'},{id:'princess',name:'Princesas Disney',tag:'Histórias encantadas',color:'#d690ac',mark:'♛'},{id:'nintendo',name:'Nintendo',tag:'Uma turma de aventuras',color:'#74b1a5',mark:'✿'},{id:'sprunki',name:'Sprunki',tag:'Cores e música',color:'#e4a66b',mark:'♪'},{id:'poppy',name:'Poppy Playtime',tag:'Encontre os personagens',color:'#7da9c9',mark:'✦'}];
const memoryLevels={easy:{name:'Fácil',pairs:4},medium:{name:'Médio',pairs:6},hard:{name:'Difícil',pairs:8}};
let memoryTheme='mixed',memoryLevel='easy',memoryRound=null,memoryRun=0,memoryStarted=0,memoryElapsed=0,memoryFrame=0,memoryMismatch=0,memorySound=true,memoryAudio=null,memoryOwnFullscreen=false;
const memoryImages=()=>window.MEMORY_IMAGES||[];
function memoryThemeImages(id){return id==='mixed'?memoryImages():memoryImages().filter(i=>i.theme===id)}

let memoryMusicLoading=null,memoryMusicSource=null;
function memoryMusicStop(){if(memoryMusicSource){memoryMusicSource.stop();memoryMusicSource.disconnect();memoryMusicSource=null;}}
function memoryMusicSync(){
 if(!memoryRound||!memorySound||document.hidden){memoryMusicStop();return;}
 if(!memoryAudio)return;
 const currentRun=memoryRun;
 if(!memoryMusicLoading)memoryMusicLoading=fetch('assets/audio/memory-garden-loop.mp3').then(r=>{if(!r.ok)throw Error('Music unavailable');return r.arrayBuffer();}).then(data=>memoryAudio.decodeAudioData(data)).catch(()=>{memoryMusicLoading=null;return null;});
 memoryMusicLoading.then(buffer=>{
  if(!buffer||currentRun!==memoryRun||!memoryRound||!memorySound||document.hidden||memoryMusicSource)return;
  const source=memoryAudio.createBufferSource(),gain=memoryAudio.createGain();source.buffer=buffer;source.loop=true;source.loopStart=0;source.loopEnd=90;gain.gain.value=.15;source.connect(gain);gain.connect(memoryAudio.destination);source.onended=()=>gain.disconnect();memoryMusicSource=source;source.start();
 });
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)memoryAudioReady();memoryMusicSync();});
function memoryStop(keepFullscreen=false){memoryMusicStop();memoryRun++;cancelAnimationFrame(memoryFrame);clearTimeout(memoryMismatch);memoryFrame=0;memoryRound=null;if(memoryOwnFullscreen&&!keepFullscreen){memoryOwnFullscreen=false;try{screen.orientation?.unlock()}catch{}if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})}}
function memoryFullScreen(){try{const requested=document.documentElement.requestFullscreen?.();Promise.resolve(requested).then(()=>{if(!document.fullscreenElement)return;if(!document.querySelector('.memory-play')){document.exitFullscreen().catch(()=>{});return}memoryOwnFullscreen=true;try{Promise.resolve(screen.orientation?.lock?.('landscape')).catch(()=>{})}catch{}}).catch(()=>{})}catch{}}
function memoryAudioReady(){if(!memorySound)return;try{memoryAudio??=new(window.AudioContext||window.webkitAudioContext)();memoryAudio.resume().catch(()=>{})}catch{}}
function memoryPlim(){if(!memorySound||!memoryAudio)return;try{const now=memoryAudio.currentTime;[880,1320,1760].forEach((frequency,index)=>{const o=memoryAudio.createOscillator(),g=memoryAudio.createGain();o.type='sine';o.frequency.value=frequency;o.connect(g);g.connect(memoryAudio.destination);g.gain.setValueAtTime(0,now+index*.055);g.gain.linearRampToValueAtTime(.075,now+index*.055+.01);g.gain.exponentialRampToValueAtTime(.001,now+.45+index*.055);o.start(now+index*.055);o.stop(now+.5+index*.055)})}catch{}}
function memoryFormatTime(ms){const sec=Math.floor(ms/1000);return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`}
function memorySetup(){memoryStop();stopSearchTimer();leaveSearchFullscreen();searchRun++;document.body.dataset.section='memory';const theme=memoryThemes.find(t=>t.id===memoryTheme);app.innerHTML=`<section class="memory-setup"><div class="memory-topline"><button id="memory-home" class="memory-back">← Todos os jogos</button><span>OBSERVAR · LEMBRAR · ENCONTRAR</span><button id="memory-sound" class="memory-sound" aria-pressed="${memorySound}">${memorySound?'♫ Som ligado':'♪ Som desligado'}</button></div><div class="memory-intro"><p class="memory-eyebrow">UM NOVO JEITO DE BRINCAR JUNTAS</p><h1>Memória <em>encantada</em><span>✧</span></h1><p>Vire uma carta. Encontre seu par.<br>Uma pequena descoberta de cada vez.</p></div><div class="memory-section-heading"><h2>1. Escolha seu universo</h2><span>Seis temas, muitas combinações</span></div><div class="memory-themes" role="group" aria-label="Tema das cartas">${memoryThemes.map(t=>{const available=memoryThemeImages(t.id),preview=available.slice(0,3);return `<button class="memory-theme" data-memory-theme="${t.id}" style="--theme:${t.color}" aria-pressed="${t.id===memoryTheme}" ${available.length<8?'disabled':''}><div class="memory-theme-art" aria-hidden="true">${preview.map((im,i)=>memoryArtwork(im,`style="--n:${i}"`)).join('')}<span>${t.mark}</span></div><strong>${t.name}</strong><small>${available.length<8?'Imagens em preparação':t.tag}</small></button>`}).join('')}</div><div class="memory-bottom"><section><h2>2. Escolha o desafio</h2><div class="memory-levels" role="group" aria-label="Dificuldade">${Object.entries(memoryLevels).map(([key,v])=>`<button data-memory-level="${key}" aria-pressed="${key===memoryLevel}"><b>${v.name}</b><span>${v.pairs} pares · ${v.pairs*2} cartas</span></button>`).join('')}</div></section><div class="memory-start-box"><p><b id="memory-choice">${theme.name}</b> <span id="memory-pairs">· ${memoryLevels[memoryLevel].pairs} pares</span></p><button id="memory-start">Vamos jogar <span>→</span></button><small>Sem limite de tempo. Cada tentativa conta!</small></div></div><details class="memory-rules"><summary>Como funciona a pontuação?</summary><p>Cada tentativa de duas cartas é um movimento. Um jogo perfeito precisa de ${memoryLevels[memoryLevel].pairs} movimentos neste nível.</p><p><b>Movimentos:</b> 10.000 × número de pares ÷ movimentos.<br><b>Tempo:</b> 100.000 ÷ segundos (mínimo de 1 segundo).<br><b>Total:</b> soma dos dois resultados. Quanto menos movimentos e tempo, mais pontos!</p></details><a class="memory-source-link" href="memory-sources.html" target="_blank" rel="noopener">Origem das imagens ↗</a></section>`;
 $('#memory-home').onclick=home;$('#memory-sound').onclick=()=>{memorySound=!memorySound;$('#memory-sound').setAttribute('aria-pressed',memorySound);$('#memory-sound').textContent=memorySound?'♫ Som ligado':'♪ Som desligado';memoryAudioReady();memoryMusicSync()};document.querySelectorAll('[data-memory-theme]').forEach(b=>b.onclick=()=>{memoryTheme=b.dataset.memoryTheme;document.querySelectorAll('[data-memory-theme]').forEach(n=>n.setAttribute('aria-pressed',n===b));$('#memory-choice').textContent=memoryThemes.find(t=>t.id===memoryTheme).name});document.querySelectorAll('[data-memory-level]').forEach(b=>b.onclick=()=>{memoryLevel=b.dataset.memoryLevel;document.querySelectorAll('[data-memory-level]').forEach(n=>n.setAttribute('aria-pressed',n===b));$('#memory-pairs').textContent=`· ${memoryLevels[memoryLevel].pairs} pares`;$('.memory-rules p').textContent=`Cada tentativa de duas cartas é um movimento. Um jogo perfeito precisa de ${memoryLevels[memoryLevel].pairs} movimentos neste nível.`});$('#memory-start').onclick=memoryStart;window.scrollTo(0,0)}
async function memoryStart(){memoryStop(true);const run=++memoryRun;memoryAudioReady();const cfg=memoryLevels[memoryLevel];let chosen;if(memoryTheme==='mixed'){const groups=MemoryCore.shuffle(memoryThemes.filter(t=>t.id!=='mixed'&&memoryThemeImages(t.id).length));chosen=[];for(const group of groups)if(chosen.length<cfg.pairs)chosen.push(MemoryCore.shuffle(memoryThemeImages(group.id))[0]);const rest=MemoryCore.shuffle(memoryImages().filter(i=>!chosen.some(c=>c.id===i.id)));chosen.push(...rest.slice(0,cfg.pairs-chosen.length))}else chosen=memoryThemeImages(memoryTheme);let deck;try{deck=MemoryCore.deckFor(chosen,cfg.pairs)}catch{notify('Este tema ainda não tem imagens suficientes.');memorySetup();return}document.body.dataset.section='memory';app.innerHTML='<section class="memory-play memory-loading"><button class="memory-back" id="memory-cancel">← Voltar</button><div><span>✧</span><h2>Preparando as cartas…</h2><p>Seu próximo desafio está chegando.</p></div></section>';$('#memory-cancel').onclick=memorySetup;memoryFullScreen();memoryResize();try{await Promise.all([...new Map(deck.map(c=>[c.image.id,c.image])).values()].map(im=>new Promise((resolve,reject)=>{const img=new Image(),timeout=setTimeout(()=>reject(Error('timeout')),20000);img.onload=()=>{clearTimeout(timeout);resolve()};img.onerror=()=>{clearTimeout(timeout);reject(Error('image'))};img.src=im.asset})));if(run!==memoryRun)return;memoryRound=MemoryCore.createRound(deck);memoryRender();memoryMusicSync();memoryStarted=Date.now();memoryElapsed=0;memoryTick()}catch{if(run!==memoryRun)return;$('.memory-loading>div').innerHTML='<h2>Uma imagem não carregou.</h2><p>Confira a conexão e tente novamente.</p><button id="memory-retry">Tentar novamente</button>';$('#memory-retry').onclick=memoryStart}}
function memoryRender(){const cfg=memoryLevels[memoryLevel],theme=memoryThemes.find(t=>t.id===memoryTheme);app.innerHTML=`<section class="memory-play" style="--memory-accent:${theme.color}"><div class="memory-game-head"><button class="memory-back" id="memory-exit" aria-label="Voltar aos temas">←</button><div><small>${theme.name}</small><h1>Encontre os pares</h1></div><div class="memory-stat"><small>MOVIMENTOS</small><b id="memory-moves">0</b></div><div class="memory-stat"><small>TEMPO</small><b id="memory-clock">0:00</b></div><div class="memory-stat"><small>PARES</small><b id="memory-matches">0 / ${cfg.pairs}</b></div><button class="memory-sound" id="memory-game-sound" aria-label="${memorySound?'Desativar':'Ativar'} som" aria-pressed="${memorySound}">${memorySound?'♫':'♪'}</button></div><div class="memory-grid-wrap"><div class="memory-grid level-${memoryLevel}">${memoryRound.deck.map((card,i)=>`<button class="memory-card" data-memory-card="${i}" aria-label="Carta ${i+1}, virada para baixo"><span class="memory-card-inner"><span class="memory-card-back" aria-hidden="true"><span class="memory-card-star">✧</span><small>ALICE & ISABELA</small></span><span class="memory-card-front" aria-hidden="true">${memoryArtwork(card.image)}<span class="memory-match-check">✓</span></span></span></button>`).join('')}</div></div><p class="memory-game-note" id="memory-feedback" role="status">Toque em duas cartas para encontrar um par.</p></section>`;$('#memory-exit').onclick=memorySetup;$('#memory-game-sound').onclick=()=>{memorySound=!memorySound;$('#memory-game-sound').setAttribute('aria-pressed',memorySound);$('#memory-game-sound').setAttribute('aria-label',memorySound?'Desativar som':'Ativar som');$('#memory-game-sound').textContent=memorySound?'♫':'♪';memoryAudioReady();memoryMusicSync()};document.querySelectorAll('[data-memory-card]').forEach(b=>b.onclick=()=>memoryFlip(+b.dataset.memoryCard));memoryResize()}
function memoryTick(){if(!memoryRound||memoryRound.finished)return;memoryElapsed=Date.now()-memoryStarted;if($('#memory-clock'))$('#memory-clock').textContent=memoryFormatTime(memoryElapsed);memoryFrame=requestAnimationFrame(memoryTick)}
function memoryUpdate(){if(!memoryRound)return;document.querySelectorAll('[data-memory-card]').forEach(b=>{const i=+b.dataset.memoryCard,c=memoryRound.deck[i],up=c.matched||memoryRound.open.includes(i);b.classList.toggle('is-up',up);b.classList.toggle('is-matched',c.matched);b.disabled=c.matched;b.setAttribute('aria-label',c.matched?`${c.image.name}, par encontrado`:up?c.image.name:`Carta ${i+1}, virada para baixo`)});$('#memory-moves').textContent=memoryRound.moves;$('#memory-matches').textContent=`${memoryRound.matches} / ${memoryRound.deck.length/2}`}
function memoryFlip(index){if(!memoryRound)return;const result=MemoryCore.reveal(memoryRound,index);if(result.type==='ignored')return;memoryUpdate();if(result.type==='match'||result.type==='complete'){memoryPlim();$('#memory-feedback').textContent='Plim! Um par encontrado!'}if(result.type==='miss'){const run=memoryRun;$('#memory-feedback').textContent='Guarde essas imagens na memória…';memoryMismatch=setTimeout(()=>{if(run!==memoryRun||!memoryRound)return;MemoryCore.conceal(memoryRound);memoryUpdate();$('#memory-feedback').textContent='Vamos tentar outro par!'},1000)}if(result.type==='complete'){memoryElapsed=Date.now()-memoryStarted;cancelAnimationFrame(memoryFrame);$('#memory-clock').textContent=memoryFormatTime(memoryElapsed);const run=memoryRun;setTimeout(()=>{if(run===memoryRun&&memoryRound?.finished)memoryFinish()},650)}}
function memoryFinish(){const pairs=memoryRound.deck.length/2,result=MemoryCore.score(pairs,memoryRound.moves,memoryElapsed),format=n=>n.toLocaleString('pt-BR');let record=0;const key=`memory-best:${memoryTheme}:${memoryLevel}`;try{record=Number(localStorage.getItem(key))||0;if(result.total>record)localStorage.setItem(key,result.total)}catch{}const dialog=document.createElement('div');dialog.className='memory-finish';dialog.innerHTML=`<section role="dialog" aria-modal="true" aria-labelledby="memory-result-title" tabindex="-1"><div class="memory-result-star">✧</div><p>${result.perfect?'MEMÓRIA PERFEITA!':'TODOS OS PARES ENCONTRADOS!'}</p><h2 id="memory-result-title">Você brilhou!</h2><strong class="memory-total">${format(result.total)}<small>pontos</small></strong><div class="memory-breakdown"><div><span>${memoryRound.moves} movimentos</span><b>${format(result.movePoints)} pts</b><small>Perfeito: ${pairs} movimentos</small></div><div><span>${(memoryElapsed/1000).toFixed(1).replace('.',',')} segundos</span><b>${format(result.timePoints)} pts</b><small>100.000 ÷ segundos</small></div></div><p class="memory-record">${result.total>record?'✦ Novo recorde neste tema e nível!':`Seu recorde: ${format(record)} pontos`}</p><div class="memory-result-actions"><button id="memory-again">Jogar de novo ↻</button><button id="memory-new-theme">Trocar tema</button></div></section>`;$('.memory-play').append(dialog);$('.memory-game-head').inert=true;$('.memory-grid-wrap').inert=true;$('#memory-again').onclick=memoryStart;$('#memory-new-theme').onclick=memorySetup;dialog.querySelector('section').focus();dialog.onkeydown=e=>{if(e.key==='Tab'){const controls=[...dialog.querySelectorAll('button')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}}
function memoryResize(){const stage=document.querySelector('.memory-play');if(!stage)return;const v=window.visualViewport,width=v?.width||innerWidth,height=v?.height||innerHeight;stage.style.setProperty('--mem-width',width+'px');stage.style.setProperty('--mem-height',height+'px');stage.style.setProperty('--mem-left',(v?.offsetLeft||0)+'px');stage.style.setProperty('--mem-top',(v?.offsetTop||0)+'px');stage.classList.toggle('memory-portrait',width<height&&width<700)}
window.addEventListener('resize',memoryResize);window.visualViewport?.addEventListener('resize',memoryResize);window.visualViewport?.addEventListener('scroll',memoryResize);document.addEventListener('fullscreenchange',memoryResize);
const memoryPreviousHome=home;home=function(){memoryStop();memoryPreviousHome();const cards=$('.game-cards');if(cards){cards.insertAdjacentHTML('beforeend',`<button class="game-card memory-portal-card" id="memory-section"><div class="game-cover memory-portal-cover">${[['one','nintendo-princess-peach'],['two','princess-moana'],['three','kpop-rumi']].map(([position,id])=>{const im=memoryImages().find(image=>image.id===id);return `<div class="memory-mini-card ${position}" role="img" aria-label="${esc(im.name)}">${memoryArtwork(im)}</div>`}).join('')}<span class="cover-badge">✧ ENCONTRE OS PARES</span></div><div class="game-card-copy"><small>LEMBRAR TAMBÉM É UMA AVENTURA</small><h2>Memória <span>↗</span></h2><p>Seus personagens favoritos em um jogo de descobertas.</p></div></button>`);$('#memory-section').onclick=memorySetup}};
const memoryPreviousChoose=choose,memoryPreviousFashion=fashion,memoryPreviousCatalog=showCatalog;choose=function(){memoryStop();return memoryPreviousChoose()};fashion=function(){memoryStop();return memoryPreviousFashion()};showCatalog=function(){memoryStop();return memoryPreviousCatalog()};home();
